function validate([n, edges, queries]) {
  if (n < 1 || n > 100000) return 'n is between 1 and 10^5.';
  if (edges.length !== n - 1) return 'edges must have exactly n - 1 entries.';
  const root = Array.from({ length: n + 1 }, (_, i) => i);
  const find = x => {
    while (root[x] !== x) x = root[x] = root[root[x]];
    return x;
  };
  const known = new Set();
  for (const edge of edges) {
    if (edge.length !== 3) return 'Each edge is [u, v, w].';
    const [u, v, w] = edge;
    if (u < 1 || u > n || v < 1 || v > n) return 'Edge endpoints are between 1 and n.';
    if (w < 1 || w > 10000) return 'Edge weights are between 1 and 10^4.';
    const a = find(u), b = find(v);
    if (a === b) return 'edges must form a tree: no cycles, loops or repeated edges.';
    root[a] = b;
    known.add(Math.min(u, v) * (n + 1) + Math.max(u, v));
  }
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  for (const query of queries) {
    if (query.length === 4 && query[0] === 1) {
      const [, u, v, w] = query;
      if (!known.has(Math.min(u, v) * (n + 1) + Math.max(u, v))) return 'An update [1, u, v, w] must name an edge of the tree.';
      if (w < 1 || w > 10000) return 'New weights are between 1 and 10^4.';
    } else if (query.length === 2 && query[0] === 2) {
      if (query[1] < 1 || query[1] > n) return 'A query [2, x] needs 1 <= x <= n.';
    } else return 'Each query is [1, u, v, w] or [2, x].';
  }
  return null;
}

