function treeQueries(n, edges, queries) {
  const adjacency = Array.from({ length: n + 1 }, () => []);
  for (const [u, v] of edges) {
    adjacency[u].push(v);
    adjacency[v].push(u);
  }
  const parent = new Array(n + 1).fill(0);
  const start = new Array(n + 1).fill(0);
  const size = new Array(n + 1).fill(1);
  const order = [];
  const stack = [1];
  while (stack.length > 0) {
    const node = stack.pop();
    order.push(node);
    start[node] = order.length;
    for (const next of adjacency[node]) {
      if (next !== parent[node]) {
        parent[next] = node;
        stack.push(next);
      }
    }
  }
  for (let i = n - 1; i > 0; i--) {
    size[parent[order[i]]] += size[order[i]];
  }
  const tree = new Array(n + 1).fill(0);
  function add(index, delta) {
    for (let i = index; i <= n; i += i & -i) {
      tree[i] += delta;
    }
  }
  function prefixSum(index) {
    let sum = 0;
    for (let i = index; i > 0; i -= i & -i) {
      sum += tree[i];
    }
    return sum;
  }
  const weight = new Array(n + 1).fill(0);
  function setWeight(u, v, newWeight) {
    const child = parent[u] === v ? u : v;
    const delta = newWeight - weight[child];
    weight[child] = newWeight;
    add(start[child], delta);
    add(start[child] + size[child], -delta);
  }
  for (const [u, v, w] of edges) {
    setWeight(u, v, w);
  }
  const answer = [];
  for (const query of queries) {
    if (query[0] === 1) {
      setWeight(query[1], query[2], query[3]);
    } else {
      answer.push(prefixSum(start[query[1]]));
    }
  }
  return answer;
}

