function treeQueries(n, edges, queries) {
  // Keep every edge's current weight and walk the whole tree from node 1 for each distance query.
  const key = (a, b) => `${Math.min(a, b)},${Math.max(a, b)}`;
  const weights = new Map();
  const neighbours = Array.from({ length: n + 1 }, () => []);
  for (const [u, v, w] of edges) {
    weights.set(key(u, v), w);
    neighbours[u].push(v);
    neighbours[v].push(u);
  }
  const result = [];
  for (const q of queries) {
    if (q[0] === 1) {
      weights.set(key(q[1], q[2]), q[3]);
      continue;
    }
    const dist = new Map([[1, 0]]);
    const queue = [1];
    for (let head = 0; head < queue.length; head++) {
      const node = queue[head];
      for (const next of neighbours[node]) {
        if (dist.has(next)) continue;
        dist.set(next, dist.get(node) + weights.get(key(node, next)));
        queue.push(next);
      }
    }
    result.push(dist.get(q[1]));
  }
  return result;
}

