function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const q = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const maxWeight = size === 'large' || rand() < 0.5 ? 10000 : 9;
  const weightOf = () => 1 + Math.floor(rand() * maxWeight);
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  // Node 1 stays the root; the other labels are shuffled. Shapes: random, deep (mostly a path), or shallow (mostly a star).
  const label = [0, 1, ...shuffle(Array.from({ length: n - 1 }, (_, i) => i + 2))];
  const shape = Math.floor(rand() * 3);
  const edges = [];
  for (let i = 2; i <= n; i++) {
    const random = 1 + Math.floor(rand() * (i - 1));
    const above = shape === 1 && rand() < 0.85 ? i - 1 : shape === 2 && rand() < 0.85 ? 1 : random;
    edges.push(rand() < 0.5 ? [label[above], label[i], weightOf()] : [label[i], label[above], weightOf()]);
  }
  shuffle(edges);
  const queries = [];
  const updateShare = 0.2 + rand() * 0.4;
  for (let t = 0; t < q; t++) {
    if (edges.length > 0 && rand() < updateShare) {
      const [u, v] = edges[Math.floor(rand() * edges.length)];
      queries.push(rand() < 0.5 ? [1, u, v, weightOf()] : [1, v, u, weightOf()]);
    } else {
      queries.push([2, 1 + Math.floor(rand() * n)]);
    }
  }
  if (!queries.some(query => query[0] === 2)) queries[q - 1] = [2, 1 + Math.floor(rand() * n)];
  return [n, edges, queries];
}
